    public virtual void DoPhysics()
    {

        force = Vector3.zero;

        // Basic forces
        force += MoveAlongGroundAndTurnAwayFromObstacles();

        // Gravity
        force += Vector3.down * parameters.gravityForce;

        // Glide near ground
        if (distanceToGround < parameters.desiredAltitude * 0.5f) {
            force += transform.forward * parameters.glideNearGroundForce;
        }

        // Curve to follow
        if (parameters.followCurve && parameters.curveToFollow) {
            force += (parameters.curveToFollow.position - transform.position).normalized * parameters.circleForce;
        }

        // Force towards/away from bird
        float distToBird = vectorToWren.magnitude;
        if (distToBird < parameters.forceTowardsBirdRadius) {
            force += vectorToWren.normalized * parameters.flockTowardsOtherBirdsForce;
        } else if (distToBird < parameters.forceAwayFromBirdRadius) {
            force -= vectorToWren.normalized * parameters.flockAwayFromOtherBirdsForce;
        }

        // Landing locations
        if (parameters.landingLocations.Length > 0 && !isLanded) {
            if (currentLandingSpot == null) currentLandingSpot = parameters.landingLocations[Random.Range(0, parameters.landingLocations.Length)];
            force += (currentLandingSpot.position - transform.position).normalized * parameters.strengthTowardsDesiredAltitude;
            if (Vector3.Distance(transform.position, currentLandingSpot.position) < 1f) {
                isLanded = true;
                velocity = Vector3.zero;
            }
        }

        // Swirl around location
        if (parameters.swirlLocation) {
            Vector3 toSwirl = parameters.swirlLocation.position - transform.position;
            Vector3 tangent = Vector3.Cross(toSwirl, Vector3.up).normalized;
            force += tangent * parameters.circleForce;
        }

        // Land and take off
        if (parameters.landAndTakeOff) {
            if (!isLanded && distToBird > parameters.forceAwayFromBirdRadius) {
                force += Vector3.down * parameters.gravityForce * 2;
                if (distanceToGround < 1f) isLanded = true;
            } else if (isLanded && distToBird < parameters.forceTowardsBirdRadius) {
                force += Vector3.up * parameters.updraft;
                isLanded = false;
            }
        }

        // Glide down mountain
        if (parameters.glideDownMountain && parameters.glideEndLocation) {
            force += (parameters.glideEndLocation.position - transform.position).normalized * parameters.glideNearGroundForce;
            if (Vector3.Distance(transform.position, parameters.glideEndLocation.position) < 1f) {
                Destroy(gameObject);
            }
        }

        // Bird type specific behaviors
        switch (parameters.birdType) {
            case PreyConfigSO.BirdType.BigMystic:
                if (parameters.curveToFollow) {
                    force += (parameters.curveToFollow.position - transform.position).normalized * parameters.speed * 0.1f;
                }
                break;
            case PreyConfigSO.BirdType.SmallFlock:
                if (parameters.bigBirdToFollow) {
                    force += (parameters.bigBirdToFollow.position - transform.position).normalized * parameters.flockTowardsOtherBirdsForce;
                }
                break;
            case PreyConfigSO.BirdType.Penguins:
                force += Vector3.down * parameters.gravityForce;
                if (distanceToGround < 1f) {
                    force += transform.forward * parameters.flapGainSpeed;
                }
                break;
            case PreyConfigSO.BirdType.Vultures:
                if (parameters.swirlLocation) {
                    Vector3 toSwirl = parameters.swirlLocation.position - transform.position;
                    Vector3 tangent = Vector3.Cross(toSwirl, Vector3.up).normalized;
                    force += tangent * parameters.circleForce;
                }
                break;
            case PreyConfigSO.BirdType.Ravens:
                if (parameters.ravenModels.Length > 0) {
                    if (!isLanded) {
                        if (currentLandingSpot == null) currentLandingSpot = parameters.ravenModels[Random.Range(0, parameters.ravenModels.Length)];
                        force += (currentLandingSpot.position - transform.position).normalized * parameters.strengthTowardsDesiredAltitude;
                        if (Vector3.Distance(transform.position, currentLandingSpot.position) < 1f) {
                            isLanded = true;
                        }
                    } else if (distToBird < parameters.forceTowardsBirdRadius) {
                        isLanded = false;
                        force += vectorToWren.normalized * parameters.runForce;
                    }
                }
                break;
            case PreyConfigSO.BirdType.Storks:
                if (distToBird < parameters.forceTowardsBirdRadius) {
                    force += Vector3.up * parameters.updraft;
                    force += Random.insideUnitSphere * parameters.noiseForce;
                }
                break;
            case PreyConfigSO.BirdType.Butterflies:
                // Basic flapping
                break;
            case PreyConfigSO.BirdType.Mantarays:
                force += transform.forward * parameters.speed * 0.5f;
                break;
            case PreyConfigSO.BirdType.FlyingFish:
                if (transform.position.y > 0) {
                    force += Vector3.down * parameters.gravityForce;
                } else {
                    force += Vector3.up * parameters.updraft;
                    DoFlapInfo();
                }
                break;
            case PreyConfigSO.BirdType.Flickers:
                if (parameters.flickerDiveAreas.Length > 0) {
                    Transform diveArea = parameters.flickerDiveAreas[Random.Range(0, parameters.flickerDiveAreas.Length)];
                    force += (diveArea.position - transform.position).normalized * parameters.flapGainSpeed;
                    if (Vector3.Distance(transform.position, diveArea.position) < 1f) {
                        force += Vector3.up * parameters.updraft;
                    }
                }
                break;
            case PreyConfigSO.BirdType.EnemyBird:
                if (distToBird < parameters.enemyAttackRadius) {
                    force += vectorToWren.normalized * parameters.runForce;
                }
                break;
        }

        // run forces
        oldVelocity = velocity;
        velocity += force * Time.deltaTime; // Assuming delta time for forces

        velocity = velocity.normalized * parameters.speed;

        velocity = GetNewVelocity( velocity , oldVelocity );
        velocity = velocity.normalized * parameters.speed;
        position += velocity * Time.deltaTime;

        DoFlapInfo();

        transform.position = position + flapValue;

    }

    public void UpdateData()
    {
        frame++;

        if ( frame % parameters.physicsResolution == 0 ) {
            rayCastData = RaycastDown();
            rawDistanceToGround = rayCastData.w;
            rawGroundNormal = new Vector3( rayCastData.x , rayCastData.y , rayCastData.z );

            rayCastData = RaycastForward();
            rawDistanceToForward = rayCastData.w;
            rawForwardNormal = new Vector3( rayCastData.x , rayCastData.y , rayCastData.z );

        }


        distanceToGround = Mathf.Lerp( distanceToGround , rawDistanceToGround , parameters.physicsInfoLerpSpeed );


        distanceToForward =
            Mathf.Lerp( distanceToForward , rawDistanceToForward - parameters.speed ,
                parameters.physicsInfoLerpSpeed ); // always want to be a little bit ahead of where we are

        groundNormal = Vector3.Lerp( groundNormal , rawGroundNormal , parameters.physicsInfoLerpSpeed );
        forwardNormal = Vector3.Lerp( forwardNormal , rawForwardNormal , parameters.physicsInfoLerpSpeed );

        forwardTurnNormalizedValue =
            Mathf.Clamp(
                (parameters.distanceForStartTurn - distanceToForward) /
                (parameters.distanceForStartTurn - parameters.distanceForHardTurn) , 0 , 1 );
        downTurnNormalizedValue = Mathf.Clamp(
            (parameters.distanceForStartTurn - distanceToGround) / (parameters.distanceForStartTurn - parameters.distanceForHardTurn) ,
            0 , 1 );

    }


    private void OnTriggerEnter( Collider c )
    {
        if ( God.IsOurWren( c ) && !spawning && Vector3.Distance(transform.position, God.wren.transform.position) <= parameters.collectionRadius ) {
            timesCollected++;
            if (parameters.hitLocationsForDestruction.Length > 0) {
                // Check if hit location
                foreach (Transform hitLoc in parameters.hitLocationsForDestruction) {
                    if (Vector3.Distance(transform.position, hitLoc.position) < 1f) { // Close enough
                        timesCollected = parameters.timesToCollectBeforeDestroy; // Force destroy
                        break;
                    }
                }
            }
            if (timesCollected >= parameters.timesToCollectBeforeDestroy) {
                manager.PreyGotAte( this );
                Destroy( gameObject );
                StartCoroutine( DestroyCoroutine( ateDieSpeed ) );
            }
        }
    }

    private void OnNotCaught()
    {
        if ( !spawning ) {
            spawning = true;
            StartCoroutine( DestroyCoroutine( dieSpeed ) );
        }
    }


    public IEnumerator DestroyCoroutine( float speed )
    {
        spawning = true;
        float startTime = Time.time;

        while (Time.time < startTime + speed) {
            float t = (Time.time - startTime) / speed;

            life = Mathf.Lerp( 1 , 0 , t );

            WhileSpawning( life );

            yield return null;
        }

        DestroyImmediate( gameObject );
        spawning = false;

    }

    public IEnumerator SpawnCoroutine( float speed )
    {

        spawning = true;
        life = 0;
        float startTime = Time.time;
        float endTime = startTime + speed;

        while (Time.time < endTime) {
            float t = (Time.time - startTime) / speed;

            life = Mathf.Lerp( 0 , 1 , t );
            WhileSpawning( life );
            yield return null;
        }

        life = 1;
        spawning = false;


    }

    public virtual void WhileSpawning( float life )
    {

        float scale = Mathf.Clamp( 1 - (life - parameters.maxScaleStartLife) , 0 , 1 );
        scale = Mathf.Min( Mathf.Clamp( 1 - (parameters.maxScaleEndLife - life) , 0 , 1 ) , scale );
        transform.localScale = Vector3.one * parameters.maxScale * scale;

    }

    public void QuickKill()
    {
        DestroyImmediate( gameObject );
    }

    public void Initialize( PreyConfigSO config , PreyManager manager )
    {
        parameters = config;
        this.manager = manager;


        SetHeight();

        force = Vector3.zero;
        frame = Random.Range( 0 , parameters.physicsResolution );


        enabled = true;
        spawnPoint = transform.position;
        startPosition = transform.position;
        position = startPosition;
        velocity = Random.insideUnitSphere.normalized * parameters.speed;
        oldVelocity = velocity;
        spawnTime = Time.time;

        life = 0;
        StartCoroutine( SpawnCoroutine( config.spawnSpeed ) );

    }


    public void SetHeight()
    {
        RaycastHit hit;

        if ( Physics.Raycast( transform.position , -transform.up , out hit , 100000 ) ) {
            float distance = hit.distance;

            transform.position = hit.point + transform.up * Mathf.Lerp( parameters.minAltitude , parameters.maxAltitude , Random.value );
            position = transform.position;
        }
    }
}

using UnityEngine;
using WrenUtils;
using System.Collections.Generic;

public class PreyManager : MonoBehaviour
{
    /*

        Can spawn in clumps for butterflies etc.

    */

    public Transform debugWren;

    public bool spawnMaxOnWrenEnter;


    [Header( "Spawn Settings" )]
    public float spawnTime;

    public float spawnDistance;


    public GameObject preyPrefab;

    public float spawnRadius;

    public Vector2 spawnHeight;


    public Vector2 spawnFoward;


    public float lastSpawnTime;


    [Header( "On Eat Effects" )]
    public float preyFullnessIncrease;

    public float        preyStaminaIncrease;
    public PreyConfigSO preyConfig;


    public bool wrenInside;

    public Transform preyHolder;


    public Transform cage;

    public int maxPray = 100;

    public Transform[] spawnPoints;
    public Transform[] objectsOfInterest;


    public bool wrenEnterOnEnabled;

    public List<Transform[]> clusters;

    public void OnEnable()
    {
        lastSpawnTime = Time.time - spawnTime;
        while (preyHolder.childCount > 0) DestroyImmediate( preyHolder.GetChild( 0 ).gameObject );

        if ( wrenEnterOnEnabled ) {
            OnWrenEnter();
        }


    }

    public void OnTriggerEnter( Collider other )
    {
        if ( God.IsOurWren( other ) ) {

            OnWrenEnter();

        }

    }

    public void OnTriggerExit( Collider other )
    {
        if ( God.IsOurWren( other ) ) {
            OnWrenExit();

        }
    }


    public int currentNumberOfPrey;

    private void Update()
    {

        currentNumberOfPrey = preyHolder.childCount;

        CheckForNewPrey();

    }

    public virtual void CheckForNewPrey()
    {
        if ( Time.time - lastSpawnTime > spawnTime && wrenInside ) {
            SpawnNewBug();
        }
    }


    public void OnWrenEnter()
    {
        wrenInside = true;
        /*
                while (preyHolder.childCount > 0)
                {
                    DestroyImmediate(preyHolder.GetChild(0).gameObject);
                }

                if (spawnMaxOnWrenEnter)
                {
                    while (preyHolder.childCount < maxPray)
                    {
                        SpawnNewBug();
                    }
                }*
                */
    }

    public void OnWrenExit()
    {
        wrenInside = false;
        /*
                while (preyHolder.childCount > 0)
                {
                    DestroyImmediate(preyHolder.GetChild(0).gameObject);
                }
          */


    }


    public int   bugsPerCluster = 1;
    public float clusterRadius  = 0;


    public enum SpawnType
    {
        RandomNearCenter ,
        RandomWithinBounds ,
        InFrontOfWren ,
        BehindWren ,
        Clustered
    }

    public enum AltitudeType
    {
        RandomRange ,
        DesiredAltitude ,
        OnGround
    }

    public SpawnType    spawnType;
    public AltitudeType altitudeType;

    public virtual void SpawnNewBug()
    {


        // destroy any over max
        while (preyHolder.childCount >= maxPray) DestroyImmediate( preyHolder.GetChild( 0 ).gameObject );


        var spawnPos = transform.position;


        if ( spawnType == SpawnType.RandomNearCenter ) {
            spawnPos = SpawnRandomNearCenter();
        } else if ( spawnType == SpawnType.RandomWithinBounds ) {
            spawnPos = SpawnRandomWithinBounds();
        } else if ( spawnType == SpawnType.InFrontOfWren ) {
            spawnPos = SpawnInFrontOfWren();
        }

        var groundPos = spawnPos;
        groundPos.y = 10000;
        RaycastHit hit;

        if ( Physics.Raycast( spawnPos , Vector3.down , out hit , 20000 ) ) {
            groundPos = hit.point + Vector3.up * spawnRadius * 2;
        }

        if ( altitudeType == AltitudeType.RandomRange ) {
            spawnPos.y = groundPos.y + preyConfig.minAltitude + Random.Range( 0 , preyConfig.maxAltitude - preyConfig.minAltitude );
        } else if ( altitudeType == AltitudeType.DesiredAltitude ) {
            spawnPos.y = groundPos.y + preyConfig.desiredAltitude;
        } else if ( altitudeType == AltitudeType.OnGround ) {
            spawnPos.y = groundPos.y;
        }

        for ( int i = 0; i < bugsPerCluster; i++ ) {

            var extraOffset = Random.insideUnitSphere * clusterRadius;
            spawnPos += extraOffset;

            var newPrey = Instantiate( preyPrefab , spawnPos , Quaternion.identity ).GetComponent<PreyController>();

            newPrey.Initialize( preyConfig , this );


            newPrey.transform.parent = preyHolder;


            lastSpawnTime = Time.time;
        }

        // }
    }


    public Vector3 SpawnRandomNearCenter()
    {
        var spawnPos = transform.position;

        var offset = Random.insideUnitSphere * spawnRadius;

        spawnPos += offset;

        return spawnPos;
    }


    public Vector3 rangeBoundsForSpawnMin;
    public Vector3 rangeBoundsForSpawnMax;

    public Vector3 SpawnRandomWithinBounds()
    {

        var spawnPos = new Vector3( Random.Range( rangeBoundsForSpawnMin.x , rangeBoundsForSpawnMax.x ) ,
            Random.Range( rangeBoundsForSpawnMin.y , rangeBoundsForSpawnMax.y ) ,
            Random.Range( rangeBoundsForSpawnMin.z , rangeBoundsForSpawnMax.z ) );

        return spawnPos;

    }

    public Vector3 SpawnInFrontOfWren()
    {
        var spawnPos = God.wren.transform.position + God.wren.transform.forward * spawnDistance;

        spawnPos.y = 10000;

        RaycastHit hit;

        if ( Physics.Raycast( spawnPos , Vector3.down , out hit , 20000 ) ) {
            spawnPos = hit.point + Vector3.up * spawnRadius * 2;
        }


        var offset = Random.insideUnitSphere * spawnRadius;

        spawnPos += offset;

        return spawnPos;

    }


    public virtual void PreyGotAte( PreyController b )
    {

        God.particleSystems.smallCollectionParticleSystem.transform.position = b.transform.position;
        God.particleSystems.smallCollectionParticleSystem.Play();

        God.audio.Play( God.sounds.eatClip );
        God.wren.stats.FullnessAdd( preyFullnessIncrease );

        God.wren.shards.CollectShards( b.parameters.numCrystals , b.parameters.crystalType , b.transform.position );


    }
}

